				for _, ext := range fmtSupportedExts {
					if strings.HasSuffix(path, ext) {
						f, openErr := os.Open(path)
						if openErr != nil {
							diags = diags.Append(fmt.Errorf("Failed to read file %s", path))
							continue
						}
						jobs = append(jobs, struct {
							name   string
							reader io.Reader
							closer io.Closer
						}{name: c.normalizePath(path), reader: f, closer: f})
						fmtd = true
						break
					}
				}
				if !fmtd {
					diags = diags.Append(fmt.Errorf("Only .tf, .tfvars, and .tftest.hcl files can be processed with terraform fmt"))
					continue
				}
			}
		}

		for _, job := range jobs {
			log.Printf("[TRACE] terraform fmt: Formatting %s", job.name)
			src, readErr := ioutil.ReadAll(job.reader)
			if job.closer != nil {
				job.closer.Close()
			}
			if readErr != nil {
				diags = diags.Append(fmt.Errorf("Failed to read %s", job.name))
				continue
			}

			c.registerSynthConfigSource(job.name, src)

			_, syntaxDiags := hclsyntax.ParseConfig(src, job.name, hcl.Pos{Line: 1, Column: 1})
			if syntaxDiags.HasErrors() {
				diags = diags.Append(syntaxDiags)
				continue
			}

			result := src
			formatted, parseDiags := hclwrite.ParseConfig(src, job.name, hcl.InitialPos)
			if parseDiags.HasErrors() {
				result = src
			} else {
				work := []struct {
					body     *hclwrite.Body
					inBlocks []string
				}{{body: formatted.Body()}}
				for len(work) > 0 {
					cur := work[len(work)-1]
					work = work[:len(work)-1]
					attrs := cur.body.Attributes()
					for name, attr := range attrs {
						tokens := attr.Expr().BuildTokens(nil)
						if len(cur.inBlocks) == 1 {
							if cur.inBlocks[0] == "variable" {
								if name == "type" {
									cur.body.SetAttributeRaw(name, c.formatTypeExpr(tokens))
									continue
								}
							}
						}

						cur.body.SetAttributeRaw(name, c.formatValueExpr(tokens))
					}

					blocks := cur.body.Blocks()
					for i := len(blocks) - 1; i >= 0; i-- {
						block := blocks[i]
						block.SetLabels(block.Labels())
						nextBlocks := append(append([]string{}, cur.inBlocks...), block.Type())
						work = append(work, struct {
							body     *hclwrite.Body
							inBlocks []string
						}{body: block.Body(), inBlocks: nextBlocks})
					}
				}
				result = formatted.Bytes()
			}

			if !bytes.Equal(src, result) {
				if c.list {
					fmt.Fprintln(stdout, job.name)
				}
				if c.write {
					writeErr := ioutil.WriteFile(job.name, result, 0644)
					if writeErr != nil {
						diags = diags.Append(fmt.Errorf("Failed to write %s", job.name))
						continue
					}
				}
				if c.diff {
					f1, diffErr := ioutil.TempFile("", "")
					if diffErr != nil {
						diags = diags.Append(fmt.Errorf("Failed to generate diff for %s: %s", job.name, diffErr))
					} else {
						f2, diffErr2 := ioutil.TempFile("", "")
						if diffErr2 != nil {
							f1.Close()
							os.Remove(f1.Name())
							diags = diags.Append(fmt.Errorf("Failed to generate diff for %s: %s", job.name, diffErr2))
						} else {
							f1.Write(src)
							f2.Write(result)
							data, cmdErr := exec.Command("diff", "--label=old/"+job.name, "--label=new/"+job.name, "-u", f1.Name(), f2.Name()).CombinedOutput()
							f1.Close()
							f2.Close()
							os.Remove(f1.Name())
							os.Remove(f2.Name())
							if len(data) > 0 {
								cmdErr = nil
							}
							if cmdErr != nil {
								diags = diags.Append(fmt.Errorf("Failed to generate diff for %s: %s", job.name, cmdErr))
							} else {
								if len(data) > 0 {
									stdout.Write(data)
								}
							}
						}
					}
				}
			}

			if !c.list && !c.write && !c.diff {
				_, writeErr := stdout.Write(result)
				if writeErr != nil {
					diags = diags.Append(fmt.Errorf("Failed to write result"))
				}
			}
		}
	}

	return diags
}

